    // Detach the fdsan owner tag from the underlying fd without closing it.
    // Used when the raw fd is transferred elsewhere (e.g. duplicated and handed
    // to another component/process), where the receiver will close it directly.
    int RemoveTag();

private:
    uint64_t Tag() const { return reinterpret_cast<uint64_t>(this); }

    int fd_ = -1;
};

UniqueFd::UniqueFd(UniqueFd &&other) noexcept
{
    fd_ = other.fd_;
    other.fd_ = -1;
    if (fd_ >= 0) {
        // The fd's fdsan owner is still the source object's tag after the move;
        // rebind it to this object so a later close matches the declared owner.
        fdsan_exchange_owner_tag(fd_, other.Tag(), Tag());
    }
}

void UniqueFd::Reset(int fd)
{
    if (fd_ >= 0) {
        fdsan_close_with_tag(fd_, Tag());
        fd_ = -1;
    }
    if (fd >= 0) {
        fd_ = fd;
        // Bind this object's owner tag to the newly adopted fd immediately,
        // restoring the fd's owner from the default 0 to Tag(), so that a later
        // fdsan_close_with_tag(fd, Tag()) matches the fd's declared owner.
        fdsan_exchange_owner_tag(fd_, 0, Tag());
    }
}

int UniqueFd::RemoveTag()
{
    if (fd_ < 0) {
        return -1;
    }
    fdsan_exchange_owner_tag(fd_, Tag(), 0);
    int fd = fd_;
    fd_ = -1;
    return fd;
}

UniqueFd &UniqueFd::operator=(UniqueFd &&other) noexcept
{
    if (this != &other) {
        Reset();
        fd_ = other.fd_;
        other.fd_ = -1;
        if (fd_ >= 0) {
            fdsan_exchange_owner_tag(fd_, other.Tag(), Tag());
        }
    }
    return *this;
}

